from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "output" / "pdf" / "BookHub_Slide_by_Slide_Speaking_Guide_Devender.pdf"
OUT.parent.mkdir(parents=True, exist_ok=True)

font_dir = Path("C:/Windows/Fonts")
if (font_dir / "arial.ttf").exists() and (font_dir / "arialbd.ttf").exists():
    pdfmetrics.registerFont(TTFont("GuideArial", str(font_dir / "arial.ttf")))
    pdfmetrics.registerFont(TTFont("GuideArialBold", str(font_dir / "arialbd.ttf")))
    REG, BOLD = "GuideArial", "GuideArialBold"
else:
    REG, BOLD = "Helvetica", "Helvetica-Bold"

TEAL = colors.HexColor("#07554F")
NAVY = colors.HexColor("#26364D")
CORAL = colors.HexColor("#C96A4C")
MINT = colors.HexColor("#E7F1EC")
CREAM = colors.HexColor("#FBF7F1")
SAND = colors.HexColor("#E9D8C2")
INK = colors.HexColor("#241C18")
MUTED = colors.HexColor("#6F625B")

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="GTitle", fontName=BOLD, fontSize=25, leading=30, textColor=INK, spaceAfter=8))
styles.add(ParagraphStyle(name="GSubtitle", fontName=REG, fontSize=12, leading=17, textColor=MUTED, spaceAfter=7))
styles.add(ParagraphStyle(name="Section", fontName=BOLD, fontSize=19, leading=23, textColor=TEAL, spaceBefore=4, spaceAfter=8))
styles.add(ParagraphStyle(name="SlideTitle", fontName=BOLD, fontSize=13.2, leading=17, textColor=NAVY, spaceAfter=4))
styles.add(ParagraphStyle(name="Label", fontName=BOLD, fontSize=8.7, leading=11, textColor=TEAL, spaceBefore=2, spaceAfter=2))
styles.add(ParagraphStyle(name="Body", fontName=REG, fontSize=9.4, leading=13.1, textColor=INK, spaceAfter=3))
styles.add(ParagraphStyle(name="Small", fontName=REG, fontSize=8.3, leading=11.5, textColor=MUTED, spaceAfter=3))

def p(text, style="Body"):
    return Paragraph(text, styles[style])

def card(slide):
    items = [
        p(f"Slide {slide['n']}: {escape(slide['title'])}", "SlideTitle"),
        p("Purpose", "Label"), p(slide["purpose"], "Body"),
        p("What to say", "Label"), p(slide["say"], "Body"),
        p("Point to on the slide", "Label"), p(slide["point"], "Body"),
        p("Transition", "Label"), p(slide["transition"], "Small"),
        p("If the teacher asks", "Label"), p(slide["question"], "Small"),
    ]
    t = Table([[items]], colWidths=[170 * mm])
    t.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), colors.white),
        ("BOX", (0, 0), (-1, -1), 0.55, SAND),
        ("LINEBEFORE", (0, 0), (0, -1), 4, CORAL if slide["n"] % 2 == 0 else TEAL),
        ("LEFTPADDING", (0, 0), (-1, -1), 10),
        ("RIGHTPADDING", (0, 0), (-1, -1), 10),
        ("TOPPADDING", (0, 0), (-1, -1), 7),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    return KeepTogether([t, Spacer(1, 7)])

slides = [
{"n":1,"title":"Internship Project Presentation - BookHub","purpose":"Introduce yourself, the project, and the context of the presentation.","say":"Good morning Sir and everyone. I am Devender, and my project is BookHub, an online bookstore and digital library management system. I built it during my Codtech MERN stack internship. It connects customers with books and gives store staff a way to manage catalog, copies, rentals, and orders.","point":"Point to your name, roll number, university, internship company, and the short list of features.","transition":"I will first explain the internship context, then the problem, design, implementation, evidence, and future scope.","question":"What is the one-line purpose of BookHub? Answer: It connects book discovery and store operations in one platform."},
{"n":2,"title":"How the presentation is organised","purpose":"Give the audience a map so they know what is coming.","say":"This presentation follows a simple path. I begin with the internship and the reason for the project. Then I explain the design, technology stack, database, main features, testing, limitations, and future work. The order moves from why the project exists to how it works.","point":"Trace the three blocks: Context, Design, and Build, then the evidence and conclusion.","transition":"I will begin with the internship that gave the project its technical direction.","question":"Why did you organise it this way? Answer: It keeps the explanation logical, from problem to solution to evidence."},
{"n":3,"title":"Internship profile and completion","purpose":"Show the academic and professional setting in which you built the project.","say":"My internship was with Codtech IT Solutions Private Limited. It focused on MERN stack web development and lasted eight weeks. The work included practical assignments, feedback, progress updates, and professional conduct. This project was the main application outcome of that learning process.","point":"Point to the company, internship ID, duration, focus, and successful completion.","transition":"The next slide explains the company environment and why it mattered to my work.","question":"What did you learn during the internship? Answer: I learned to connect frontend screens, backend APIs, database rules, testing, and documentation in one project."},
{"n":4,"title":"About Codtech IT Solutions","purpose":"Explain the company context without claiming unsupported details.","say":"Codtech provided a technology-services and learning environment. The internship encouraged learning by building, discussing progress, collaborating, and applying feedback. That mattered because BookHub was developed as an end-to-end product, not just as isolated screens.","point":"Point to the company name, information technology services, and the three learning outcomes.","transition":"With that context, I can now introduce the product itself.","question":"How did the company influence the project? Answer: It encouraged practical delivery, documentation, communication, and improvement through feedback."},
{"n":5,"title":"BookHub at a glance","purpose":"Give the shortest complete description of the system.","say":"BookHub is a single-store bookstore platform for Rewari. Customers can discover books, buy or rent physical copies, access eligible digital reading, save books, follow orders, and receive updates. Staff can manage catalog records, inventory locations, orders, rentals, and operational signals.","point":"Point to the customer side and staff side, then repeat the product promise: every title discoverable and every copy traceable.","transition":"The next slide explains why a bookstore needs more than a simple book list.","question":"Who is the target user? Answer: Customers are the main self-service users, while inventory staff, managers, and owners operate the store."},
{"n":6,"title":"Why this project was needed","purpose":"Create motivation and show the real-world gap.","say":"For readers, finding a title is only the first step. They also need to know whether it is available, rentable, digital, or reserved. For stores, catalog, shelf locations, orders, rental status, and customer updates are often separated. BookHub brings these parts together and also gave me a practical way to learn full-stack development.","point":"Point to the reader problem, store problem, and learning value.","transition":"That leads to the exact problem statement.","question":"What problem does BookHub solve? Answer: It reduces the gap between customer discovery and the store's operational information."},
{"n":7,"title":"Problem statement","purpose":"State the central question in a form the teacher can remember.","say":"The central question is: how can a local bookstore provide modern self-service without losing operational control? A customer needs confidence about availability, format, price, rental dates, order progress, and digital expiry. A fragmented process makes these states unclear.","point":"Point to the core problem and the four broken areas: stock, orders, digital access, and staff updates.","transition":"The proposed answer is one connected operational flow.","question":"Why is digital expiry important? Answer: Digital access should stop when the customer's rental entitlement expires, so the backend must check it."},
{"n":8,"title":"From fragmented tasks to one operational flow","purpose":"Compare the old style of working with the BookHub approach.","say":"This is a conceptual comparison, not a claim of measured performance. A fragmented store may use a static list, a manual stock check, and separate messages. BookHub uses search and sections, BookCopy status, linked orders and rentals, and notifications in one flow.","point":"Read one row from the comparison, such as Discovery or Availability, rather than reading every cell.","transition":"The objectives define what this connected flow must achieve.","question":"Is the comparison based on a measured study? Answer: No, it explains the design difference and does not invent performance percentages."},
{"n":9,"title":"What BookHub is designed to achieve","purpose":"Separate the project objectives from the project boundaries.","say":"The objectives are to create a polished discovery experience, support purchase and both rental journeys, track copies and shelf locations, and give customers and owners the right visibility. The current scope includes catalog, authentication, cart, demo checkout, rentals, digital access, notifications, wishlist, reservations, inventory, and security middleware.","point":"Point to the objectives first, then the implemented-now scope boundary.","transition":"Different users need different parts of this scope.","question":"What is outside the current scope? Answer: A live payment provider, production private PDF storage, deeper supplier workflows, and multi-branch transfers are future work."},
{"n":10,"title":"Who uses the system?","purpose":"Explain roles and why role-aware access is necessary.","say":"BookHub has customer self-service and staff operations. Customers browse, buy, rent, reserve, review, and manage their account. Inventory staff manage copies, locations, checkouts, and returns. Managers manage catalog, customers, orders, and reports. Owners have the broadest business access.","point":"Point to each role and give one example action for it.","transition":"These roles connect to a wider capability map.","question":"How are roles protected? Answer: The backend authenticates the user and checks the role before allowing protected operations."},
{"n":11,"title":"The BookHub capability map","purpose":"Show the project as connected areas rather than isolated pages.","say":"The capability map has five connected areas. Discover covers home, sections, search, and filters. Engage covers wishlist, reviews, and reservations. Transact covers cart, orders, and demo payments. Access covers physical rentals and digital reading. Operate covers inventory, staff workflows, and notifications.","point":"Move clockwise through the map and explain that the shared operational core connects them.","transition":"The next slides explain the technology that makes this map work.","question":"Which capability is most important? Answer: The value comes from their connection, especially catalog, inventory, order, rental, and notification state."},
{"n":12,"title":"The verified implementation stack","purpose":"Name the actual technologies and their jobs.","say":"The client uses React and Vite. React builds the screens and Vite runs and bundles the app. React Router handles URLs, while the current source uses React Context for login and cart state. Axios connects the client to the API. The server uses Node.js and Express. MongoDB Atlas stores data through Mongoose. JWT, bcrypt, Zod, Helmet, CORS, and rate limiting add security and validation.","point":"Point to one technology at a time and say its job rather than only reading the name.","transition":"The next slide explains the frontend stack with a BookHub example.","question":"Why use one main language? Answer: JavaScript across client and server reduces context switching and keeps the stack consistent for a small project."},
{"n":13,"title":"Frontend technologies in context","purpose":"Explain how the browser side becomes reusable screens.","say":"React builds each screen from reusable pieces, such as a BookCard. The same card pattern can appear on the home page, section pages, catalog, wishlist, and related books. React Router moves between pages. Axios sends requests. Context keeps login and cart information available. The styling combines Tailwind tooling with custom CSS for the BookHub theme.","point":"Point to the BookCard example and the supporting frontend pieces.","transition":"The server then becomes the authority for rules and permanent changes.","question":"Why is component reuse useful? Answer: One change to a shared component can improve several screens and reduces duplicated code."},
{"n":14,"title":"Backend and API responsibilities","purpose":"Explain the server request path in simple words.","say":"The backend is the authority for authentication, business rules, and durable state changes. Routes are the named doors, such as books, orders, and rentals. Controllers read the request and prepare a response. Services apply rules such as copy availability or rental expiry. Models describe how data is stored. In one sentence: request, rule, database, response.","point":"Point to Routes, Controllers, Services, and Models in order.","transition":"Those models store the operational data in MongoDB Atlas.","question":"Why keep rules on the server? Answer: The browser can be changed by a user, so important rules must be enforced in trusted backend code."},
{"n":15,"title":"MongoDB Atlas and the operational data model","purpose":"Explain why the database fits the bookstore domain.","say":"MongoDB stores related documents in collections. Mongoose gives those documents schemas, references, and validation. Book stores title information, while BookCopy stores each physical copy, its status, and location. Orders and rentals keep their own history. MongoDB Atlas provides the shared cloud database used by the application.","point":"Point to the Book versus BookCopy distinction and the key collections.","transition":"The architecture slide shows how the client, API, and database connect.","question":"Why separate Book and BookCopy? Answer: One title can have many copies, each with its own condition, availability, and shelf location."},
{"n":16,"title":"System architecture","purpose":"Show the complete technical boundary of the product.","say":"The React client contains pages, components, state, and the API client. It sends JSON requests to the Express API. The API contains routes, controllers, services, and validation. MongoDB Atlas stores users, books, copies, orders, rentals, and notifications. Future production storage would protect covers and PDFs using private storage and short-lived signed URLs.","point":"Trace the arrows from React client to Express API to MongoDB Atlas, then point to future storage.","transition":"Now I will follow one customer action through this architecture.","question":"Where should authorization happen? Answer: It should happen in server middleware and business rules, not only by hiding a button in React."},
{"n":17,"title":"End-to-end customer order flow","purpose":"Explain the main customer journey step by step.","say":"The customer discovers a title, chooses purchase or rental, reviews the cart, and places the order. The backend creates the order and demo payment record, then the owner can review it. Depending on the choice, the system also creates physical rental or digital access information and notifications.","point":"Trace Discover, Choose, Cart, and the later order state changes.","transition":"The data behind this flow is explained through the entity relationship view.","question":"What happens after checkout? Answer: The system stores the order and demo payment, then the relevant rental, access, inventory, and notification records are updated."},
{"n":18,"title":"Entity-Relationship view","purpose":"Show the important entities and relationships.","say":"The ER view explains the database structure. User connects to orders, rentals, reservations, reviews, wishlist, and notifications. Book connects to author, category, publisher, and many BookCopy records. BookCopy points to a Location. Orders contain items, and rentals connect a customer to a book or copy for a time period.","point":"Point to primary keys, foreign keys, and the Book to BookCopy relationship.","transition":"With the data model in place, I can show the user-facing catalog features.","question":"What is a foreign key? Answer: It is a stored reference that links one record to another, such as BookCopy.bookId pointing to Book."},
{"n":19,"title":"Catalog and section discovery","purpose":"Explain how the homepage helps users browse naturally.","say":"BookHub uses curated sections such as Fiction, Science Fiction, Fantasy, Romance, Mythology and Folklore, and Biography and Memoir. Book cards show category, title, author, rating, cover, and wishlist action. This gives the catalog a human browsing rhythm instead of showing an unstructured list.","point":"Point to section cards and then to the reusable book card anatomy.","transition":"A growing catalog also needs search and filter controls.","question":"Why use sections? Answer: Sections reduce browsing effort and let the store organise books in a way users understand."},
{"n":20,"title":"Search, filters, and sort controls","purpose":"Demonstrate how customers find a book quickly.","say":"The catalog supports search by title, author, or ISBN, along with category, format, and sort controls. When the customer types, the catalog query narrows the results. When the search is cleared, the filter becomes empty and the full book list appears again. This keeps the interaction predictable.","point":"Point to the search box, category, format, sort dropdown, and results count.","transition":"Once a customer chooses a book, the account and personal services become important.","question":"How do you handle an empty search? Answer: An empty query removes the filter, so the client requests or displays all books again."},
{"n":21,"title":"Accounts and profile experience","purpose":"Explain why authentication is more than a login screen.","say":"Registration creates a customer identity with password rules. Login creates an authenticated session so protected routes can load personal data. The profile page brings together identity, role, status, store, orders, rentals, wishlist, and digital access. This turns a public catalog into a personalised service.","point":"Point to Registration, Login, and Profile as three stages.","transition":"The authenticated customer can save books and continue into commerce.","question":"What is authentication? Answer: It verifies who the user is. Authorization is the separate check for what that user may do."},
{"n":22,"title":"Wishlist, cart, and payment history","purpose":"Explain the commerce flow and the demo-payment boundary.","say":"The wishlist stores customer intent for later. The cart holds selected titles, formats, quantities, and totals before the order. Payment history records what the application created for review. The current payment status is explicitly demo mode, so I do not claim that real money is processed.","point":"Point to the three areas and the demo payment wording.","transition":"After an order or rental changes state, the customer needs clear updates and access rules.","question":"Is a real payment gateway connected? Answer: No. The project uses a demo payment record. A production version would add a provider and webhook verification."},
{"n":23,"title":"Notifications and digital access","purpose":"Explain event updates and protected digital reading.","say":"Notifications store events such as order confirmation, rental start, due dates, overdue status, and digital access changes. The digital library checks the entitlement every time a rental is opened. The backend confirms that the rental is active and not expired. Private object storage and signed URLs are future production work.","point":"Point to the notification centre, expiry date, and open digital edition action.","transition":"The owner dashboard shows the same operational state from the staff side.","question":"Why check digital access on every open? Answer: It prevents an expired rental from remaining usable just because an old page is still open."},
{"n":24,"title":"Owner dashboard and operational visibility","purpose":"Show how the owner sees the store in one view.","say":"The dashboard turns bookstore state into compact signals: total titles, total copies, available copies, rented copies, overdue rentals, customers, orders, and revenue. These values help the owner decide what needs attention without opening every record.","point":"Point to the metric cards and explain one operational decision, such as checking overdue rentals.","transition":"The dashboard is useful because the inventory model records each copy and its location.","question":"What is a dashboard metric? Answer: It is a summary value calculated from operational records to help a manager monitor the store."},
{"n":25,"title":"Inventory, branches, shelves, and sections","purpose":"Explain physical inventory and the location hierarchy.","say":"A physical copy becomes useful when the store knows where it is. BookHub models branch, floor, section, rack, and shelf. The owner can add a title, assign a section, add cover and PDF metadata, set prices and rental rules, and create the required number of copies.","point":"Trace the location chain from branch down to shelf and then point to the add-title workflow.","transition":"After an order is placed, the owner can review and confirm it.","question":"Why track the exact shelf? Answer: It makes a copy findable for staff and makes availability more trustworthy for customers."},
{"n":26,"title":"Order review and owner confirmation","purpose":"Explain the status transition after a customer submits an order.","say":"The customer order can remain placed while the owner reviews it. The owner sees the request and uses an explicit acceptance action. The order moves from PLACED to CONFIRMED, and the customer receives a professional notification. This separates a request from a confirmed store action.","point":"Point to PLACED, owner review, and CONFIRMED.","transition":"The next enlarged views make the interface details easier to see.","question":"Why not confirm every order automatically? Answer: A physical store may need to verify stock, copies, or owner approval before confirming."},
{"n":27,"title":"Discovery sections - enlarged view","purpose":"Show the home-page taxonomy clearly.","say":"This enlarged view shows how the home page presents sections as a visual browsing path. I would point out the section name, the visible book count, and the arrow that opens that section. The count is derived from the books assigned to that section, so it changes when titles are added or removed.","point":"Point to the section cards, thumbnails, counts, and explore link.","transition":"Inside a section, users see consistent book cards.","question":"Why enlarge this screenshot? Answer: The full interface is dense, so the enlarged view makes the actual interaction legible to the audience."},
{"n":28,"title":"Book cards - enlarged view","purpose":"Explain the reusable unit customers scan while browsing.","say":"Each card gives the customer the key decision information: section, cover, title, author, rating or review signal, and wishlist action. Consistent cards make the catalog easier to scan and reuse the same visual language on several pages.","point":"Point to the cover, title, author, category, rating, and heart action.","transition":"When a customer selects several cards, the cart brings the choices together.","question":"What happens if a cover URL fails? Answer: The interface should use a fallback visual and still preserve the title and metadata."},
{"n":29,"title":"Cart and checkout - enlarged view","purpose":"Explain the final customer review before the order is created.","say":"The cart shows selected books, the format, quantity controls, line prices, and the order summary. The customer can check the total before placing the order. The project keeps the checkout flow clear while marking the payment mode as demo.","point":"Point to quantity controls, format-aware price, order summary, and Place order.","transition":"Digital rentals have a similar customer-facing view, but they also need expiry information.","question":"Why show format-aware pricing? Answer: A purchase, physical rental, and digital rental can have different prices and access rules."},
{"n":30,"title":"Digital library - enlarged view","purpose":"Show how time-limited digital access is presented.","say":"The digital library shows the title, active badge, expiry date, rental charge, and an open digital edition action. The visible button is only one part of the design. The backend checks the active entitlement again before it opens the reader.","point":"Point to Active, expiry, rental charge, and Open digital edition.","transition":"The owner view gives a different perspective on the same system state.","question":"What happens after expiry? Answer: The backend rejects the open request and the customer cannot continue using that rental."},
{"n":31,"title":"Admin dashboard - enlarged view","purpose":"Focus the teacher on the management signals.","say":"This enlarged dashboard view makes the management information readable. The owner can see books, copies, customers, orders, overdue rentals, and revenue in one place. It is a summary layer over the underlying collections and workflows.","point":"Point to the metric cards, not just the page title.","transition":"The next view shows how the owner acts on an order.","question":"Who can open the visible admin portal? Answer: The current frontend restricts the admin page to manager and owner accounts."},
{"n":32,"title":"Order acceptance - enlarged view","purpose":"Make the status workflow easy to explain.","say":"This view shows a professional status change. The owner reviews a placed order and confirms it. The system then communicates the change to the customer through a notification. A clear state transition is easier to understand than a hidden database update.","point":"Point to PLACED, Owner review, CONFIRMED, and the notification statement.","transition":"The next operational example is physical inventory placement.","question":"What is a state transition? Answer: It is a controlled change from one business status to another, such as placed to confirmed."},
{"n":33,"title":"Inventory placement - enlarged view","purpose":"Explain how a physical copy gets a real store location.","say":"The owner can create a branch and shelf hierarchy and attach titles to operational locations. The chain is branch, floor, section, rack, then shelf. This gives staff a repeatable way to find and count copies.","point":"Trace the five location levels from top to bottom.","transition":"Now I will combine discovery, checkout, inventory, and notification in one realistic story.","question":"What if a store has multiple branches? Answer: The location hierarchy already provides a foundation; future work would add transfers and branch-specific reporting."},
{"n":34,"title":"A realistic BookHub scenario","purpose":"Tell the complete story without jumping between features.","say":"A customer finds a title in a section and checks the card. They choose purchase or rental, add it to the cart, and place the order. The cart clears, a demo payment record is created, the owner reviews the request, and the customer receives a status update. If it is a rental, the appropriate copy or digital entitlement is tracked.","point":"Follow steps 1 to 3 and then explain the remaining state changes in one sentence.","transition":"A credible project also needs documented checks.","question":"Why use a scenario? Answer: It proves that the modules form one workflow instead of existing as unrelated pages."},
{"n":35,"title":"Testing and validation","purpose":"Explain what was checked without inventing results.","say":"The project includes a backend smoke test for core API areas, frontend linting, a Vite production build, a combined project check, and a production readiness check. I will report actual command output if asked, but I will not invent pass percentages. The important point is that the checks target API behaviour, code quality, and bundle readiness.","point":"Point to each check and the evidence boundary at the bottom.","transition":"Testing checks correctness, while security controls reduce common risks.","question":"What is a smoke test? Answer: It is a quick check that the most important parts of the application respond and work at a basic level."},
{"n":36,"title":"Security and reliability boundaries","purpose":"Show the small controls that protect the application.","say":"BookHub uses several layers of protection. JWT and refresh sessions support identity. bcrypt hashes passwords. Role and ownership checks protect actions. Zod and ObjectId validation check input. Sanitization, Helmet, CORS, rate limiting, and central error handling reduce common API risks. These controls work together rather than relying on one feature.","point":"Point to Identity, Authorization, Input safety, and Data handling.","transition":"A good academic presentation also states the current limitations honestly.","question":"What is the difference between authentication and authorization? Answer: Authentication identifies the user; authorization checks the permissions for that user."},
{"n":37,"title":"Current limitations and challenges","purpose":"Show honesty and explain the challenges you solved.","say":"The current version is a strong functional demonstration, not a finished commercial platform. Payments are demo-only, external messaging is not connected, private PDF storage is future work, and deeper multi-branch workflows are deferred. During development I solved search matching, copy-level inventory, combined buy/rent/reserve/digital choices, and consistent customer and owner status updates.","point":"Point to the limitations first, then the four challenge statements.","transition":"The future-enhancement slide shows how these limitations could be addressed.","question":"What challenge was most important? Answer: Keeping catalog titles separate from physical copies while still giving customers simple availability information."},
{"n":38,"title":"Future enhancements","purpose":"Separate proposed improvements from completed features.","say":"The high-priority improvements are a real payment gateway with verified webhooks, private PDF object storage with short-lived signed URLs, and automated browser tests. Medium-priority work includes email or SMS adapters, richer branch reports, transfers, and accessibility improvements. These are proposals, not current claims.","point":"Point to the priority labels and the distinction between current work and future work.","transition":"The next slide summarises what the project taught me.","question":"Which future improvement would you build first? Answer: Private PDF storage or a verified payment flow, because both affect production safety."},
{"n":39,"title":"What I achieved and learned","purpose":"Summarise the academic value of the project.","say":"BookHub helped me practise a full product narrative, stateful customer workflows, operational data modelling, and a security mindset. I learned that a useful application needs more than attractive screens. It also needs clear data relationships, server-side rules, testing, and honest documentation of limitations.","point":"Point to the four numbered learning outcomes.","transition":"I will close by summarising the problem, solution, and value.","question":"What was your biggest learning? Answer: Connecting UI actions to reliable backend state and explaining the system clearly."},
{"n":40,"title":"BookHub turns a bookstore into a connected experience","purpose":"End with the problem, solution, value, and an invitation for questions.","say":"To conclude, the original problem was fragmented discovery, availability, orders, rentals, and updates. BookHub addresses it with a MERN-stack platform that connects customer and owner workflows. The value is clearer decisions, traceable stock, and professional status communication. Thank you. I welcome your questions and feedback.","point":"Point to Problem, Solution, and Value, then pause before inviting questions.","transition":"There is no next slide. Stop speaking and take the teacher's questions.","question":"What is the final message? Answer: BookHub connects customer experience and bookstore operations around one reliable source of state."},
]

def page_header_footer(canvas, doc):
    canvas.saveState()
    w, h = A4
    if doc.page > 1:
        canvas.setFillColor(TEAL)
        canvas.rect(0, h - 7 * mm, w, 7 * mm, fill=1, stroke=0)
        canvas.setFont(REG, 7.8)
        canvas.setFillColor(MUTED)
        canvas.drawString(20 * mm, h - 14 * mm, "BookHub slide-by-slide speaking guide")
        canvas.drawRightString(w - 20 * mm, h - 14 * mm, "Devender")
    canvas.setStrokeColor(SAND)
    canvas.line(20 * mm, 14 * mm, w - 20 * mm, 14 * mm)
    canvas.setFont(REG, 8)
    canvas.setFillColor(MUTED)
    canvas.drawString(20 * mm, 8 * mm, "Speak naturally. Explain the idea, then point to the evidence.")
    canvas.drawRightString(w - 20 * mm, 8 * mm, f"Page {doc.page}")
    canvas.restoreState()

doc = BaseDocTemplate(str(OUT), pagesize=A4, rightMargin=20 * mm, leftMargin=20 * mm, topMargin=22 * mm, bottomMargin=20 * mm, title="BookHub Slide by Slide Speaking Guide", author="Devender")
frame = Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height, id="main")
doc.addPageTemplates([PageTemplate(id="guide", frames=frame, onPage=page_header_footer)])
